from fastapi import FastAPI, Response, status
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/none", status_code=status.HTTP_204_NO_CONTENT)
def read_none() -> None:
    return None

@app.get("/str-none", status_code=status.HTTP_204_NO_CONTENT)
def read_str_none() -> "None":
    return None

client = TestClient(app)

def test_none():
    response = client.get("/none")
    print(f"None: {response.status_code}")
    assert response.status_code == 204

def test_str_none():
    response = client.get("/str-none")
    print(f"Str None: {response.status_code}")
    assert response.status_code == 204

if __name__ == "__main__":
    test_none()
    test_str_none()
    print("All tests passed!")

